#[test]
fn option_unwrap_and_or_preserve_channel_direction() { for (src, want) in [("fn f(rc <-chan int) {\n    close(some(rc).unwrap())\n}\n", "HYB-E3009"), ("fn f(rc <-chan int) {\n    close(some(rc).or(rc))\n}\n", "HYB-E3009"), ("fn f(rc <-chan int) {\n    var out chan<- int = some(rc).unwrap()\n    _ = out\n}\n", "HYB-E3012"), ("fn f(rc <-chan int) {\n    var out chan<- int = some(rc).or(rc)\n    _ = out\n}\n", "HYB-E3012")] { let r = hy_check::check_file(&hy_syntax::parse_file("t.hy", src).unwrap()); assert!(r.diagnostics.iter().any(|d| d.code == want), "{src}: {:?}", r.diagnostics); } assert!(hy_check::check_file(&hy_syntax::parse_file("t.hy", "fn f(ch chan int) {\n    var out chan<- int = some(ch).unwrap()\n    _ = out\n    close(some(ch).or(ch))\n}\n").unwrap()).diagnostics.is_empty()); }
